interface PricingStrategy { double price(double base); }
class RegularPricing implements PricingStrategy {...}
class VipPricing implements PricingStrategy {...}

class Cart {
    private final PricingStrategy pricing;   // injected
    Cart(PricingStrategy p) { this.pricing = p; }
    double total(double base) { return pricing.price(base); }
}
